	private function wrap(string $html): string { return '<div class="ProcessMessenger pw-module-workspace">' . $html . '</div>'; }
	private function csrf(): string { $token=$this->wire('session')->CSRF->getToken();return '<input type="hidden" name="' . $this->e($token['name']) . '" value="' . $this->e($token['value']) . '">'; }
	private function e($value): string { return $this->wire('sanitizer')->entities((string)$value); }
}
